import type { FC } from 'react';
import { useMemo } from 'react';

import {
  BasicContainer,
  BigNumber,
  ChartHeader,
  ErrorContainer,
  NoDataYet,
  Skeleton,
} from 'components';
import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle } from 'hooks';
import { AISummary } from 'pages/components/AISummary';
import { AI_SUMMARY_PAGE_IDENTIFIERS } from 'pages/constants';

import { FILTER_CONFIGS } from '../../../../constants';
import {
  StyledAiSummarySection,
  StyledCardsGrid,
  StyledContainer,
  StyledStateContainer,
} from './OverTimePerformance.styles';
import type { OverTimePerformanceProps } from './types';

const POSTOOL_OVERVIEW_AI_SUMMARY_PAGE_IDENTIFIER =
  AI_SUMMARY_PAGE_IDENTIFIERS.POS_TOOL_OVERVIEW_OVER_TIME_PERFORMANCE;

export const OverTimePerformance: FC<OverTimePerformanceProps> = ({
  bigNumbers,
  isLoading = false,
  error = false,
  dataTestId,
  selectedKPI,
  onKPISelect,
  onRetry,
}) => {
  const [aiSummaryEnabled, aiSummaryToggleLoading] = useFeatureToggle(
    featureToggles.pillar.category.submenus.posTool.tab.overview.aiSummary,
  );

  const showAiSummary = useMemo(
    () => aiSummaryEnabled === true && !aiSummaryToggleLoading,
    [aiSummaryEnabled, aiSummaryToggleLoading],
  );

  if (isLoading && !bigNumbers) {
    return (
      <Skeleton
        length={1}
        width="100%"
        height="300px"
        borderRadius="large"
        dataTestId={
          dataTestId
            ? `${dataTestId}-over-time-performance-skeleton`
            : undefined
        }
      />
    );
  }

  if (error) {
    const errorTestId = dataTestId
      ? `${dataTestId}-over-time-performance-error`
      : 'over-time-performance-error';

    return (
      <BasicContainer
        header={{ title: 'Over Time Performance', titleSize: 'H2' }}
        layout={{ bodyPadding: false, background: '#F9F9F9' }}
        dataTestId={
          dataTestId ? `${dataTestId}-over-time-performance` : undefined
        }
      >
        <StyledStateContainer>
          <ErrorContainer
            title="We couldn't load this data"
            message="Something went wrong. Please try again."
            actions={Boolean(onRetry)}
            actionOne="Try again"
            handleActionOne={onRetry}
            dataTestId={errorTestId}
          />
        </StyledStateContainer>
      </BasicContainer>
    );
  }

  if (!bigNumbers) {
    return (
      <NoDataYet
        dataTestId={
          dataTestId ? `${dataTestId}-over-time-performance-no-data` : undefined
        }
      />
    );
  }

  const aiSummaryTestIdBase = dataTestId
    ? `${dataTestId}-over-time-performance-ai-summary`
    : 'over-time-performance-ai-summary';

  return (
    <BasicContainer
      header={{
        title: 'Over Time Performance',
        titleSize: 'H2',
      }}
      layout={{ bodyPadding: false, background: '#F9F9F9' }}
      dataTestId={
        dataTestId ? `${dataTestId}-over-time-performance` : undefined
      }
    >
      <StyledContainer>
        <StyledCardsGrid>
          {bigNumbers.map((cardData) => (
            <BigNumber
              key={cardData.kpiKey}
              header={
                <ChartHeader
                  title={cardData.title}
                  measure={cardData.measure}
                  period={cardData.period}
                  config={{ inline: 'horizontal', type: 'large' }}
                />
              }
              data={cardData.data}
              emptyStateMessage={cardData.emptyStateMessage}
              emptyStateConfig={{
                inline: true,
                imageSize: {
                  height: '44px',
                  width: '44px',
                },
              }}
              asCard
              size="small"
              onClick={
                onKPISelect && cardData.data.length > 0
                  ? () => onKPISelect(cardData.kpiKey)
                  : undefined
              }
              isSelected={selectedKPI === cardData.kpiKey}
              dataTestId={
                dataTestId ? `${dataTestId}-${cardData.dataTestId}` : undefined
              }
            />
          ))}
        </StyledCardsGrid>

        {showAiSummary && (
          <StyledAiSummarySection>
            <AISummary
              pageName={FILTER_CONFIGS.pageName}
              summaryPageIdentifier={
                POSTOOL_OVERVIEW_AI_SUMMARY_PAGE_IDENTIFIER
              }
              kpiGroup="pos"
              dataTestId={aiSummaryTestIdBase}
              hasExpandedAction={true}
            />
          </StyledAiSummarySection>
        )}
      </StyledContainer>
    </BasicContainer>
  );
};
